<?php require_once __DIR__.'/../includes/functions.php';role('teacher');$cid=(int)($_GET['id']??0);$tid=$_SESSION['user_id'];$s=$conn->prepare('SELECT c.* FROM courses c JOIN users u ON u.id=? LEFT JOIN professors p ON p.id=c.professor_id WHERE c.id=? AND (c.teacher_id=u.id OR p.email=u.email)');$s->bind_param('ii',$tid,$cid);$s->execute();$course=$s->get_result()->fetch_assoc();if(!$course)exit('Course not found or access denied.');$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();try{$act=$_POST['action']??'';if($act==='material'){$f=upload_one($_FILES['material']??null,'materials');if(!$f)throw new RuntimeException('Choose a file.');$s=$conn->prepare('INSERT INTO materials(course_id,teacher_id,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?,?)');$s->bind_param('iisssi',$cid,$tid,$f['original_name'],$f['stored_name'],$f['mime_type'],$f['file_size']);$s->execute();$msg='Material uploaded successfully.';}elseif($act==='announcement'){$t=trim($_POST['title']);$b=trim($_POST['body']);$s=$conn->prepare('INSERT INTO announcements(course_id,teacher_id,title,body) VALUES(?,?,?,?)');$s->bind_param('iiss',$cid,$tid,$t,$b);$s->execute();$msg='Announcement posted.';}elseif($act==='assignment'){$t=trim($_POST['title']);$b=trim($_POST['instructions']);$due=$_POST['due_date']?:null;$s=$conn->prepare('INSERT INTO assignments(course_id,teacher_id,title,instructions,due_date) VALUES(?,?,?,?,?)');$s->bind_param('iisss',$cid,$tid,$t,$b,$due);$s->execute();$msg='Assignment created.';}}catch(Throwable $x){$err=$x->getMessage();}}
$s=$conn->prepare('SELECT * FROM materials WHERE course_id=? ORDER BY uploaded_at DESC');$s->bind_param('i',$cid);$s->execute();$mats=$s->get_result();$s=$conn->prepare('SELECT * FROM announcements WHERE course_id=? ORDER BY created_at DESC');$s->bind_param('i',$cid);$s->execute();$anns=$s->get_result();$s=$conn->prepare('SELECT * FROM assignments WHERE course_id=? ORDER BY created_at DESC');$s->bind_param('i',$cid);$s->execute();$ass=$s->get_result();$page_title=$course['title'];include __DIR__.'/../includes/header.php';?><p><a href="courses.php">← My courses</a></p><h1><?=e($course['title'])?></h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><div class="grid two"><div class="card"><h2>Post announcement</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="announcement"><label>Title</label><input name="title" required><label>Message</label><textarea name="body" required></textarea><button class="btn">Post</button></form></div><div class="card"><h2>Create assignment</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="assignment"><label>Title</label><input name="title" required><label>Instructions</label><textarea name="instructions"></textarea><label>Due date</label><input type="datetime-local" name="due_date"><button class="btn">Create assignment</button></form></div></div><div class="card"><h2>Upload learning material</h2><p class="muted">PDF, DOC/DOCX, PPT/PPTX, XLS/XLSX, PNG/JPG/GIF, TXT, ZIP · max 10 MB</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="material"><input type="file" name="material" required><button class="btn">Upload file</button></form></div><div class="grid two"><div class="card"><h2>Announcements</h2><?php while($a=$anns->fetch_assoc()):?><p><b><?=e($a['title'])?></b><br><?=nl2br(e($a['body']))?></p><hr><?php endwhile;?></div><div class="card"><h2>Assignments</h2><?php while($a=$ass->fetch_assoc()):?><p><b><?=e($a['title'])?></b><br><?=nl2br(e($a['instructions']))?><br><a href="<?=BASE_URL?>/teacher/submissions.php?id=<?=$a['id']?>">View submissions</a></p><hr><?php endwhile;?></div></div><div class="card"><h2>Uploaded materials</h2><?php while($m=$mats->fetch_assoc()):?><p>📎 <?=e($m['original_name'])?> · <a href="<?=BASE_URL?>/download.php?type=material&id=<?=$m['id']?>">Download</a></p><?php endwhile;?></div><?php include __DIR__.'/../includes/footer.php';?>
